const data = $input.first().json;
if (data.code !== 200) throw new Error('Suno Fehler: ' + data.msg);
const taskId = data?.data?.taskId || '';
if (!taskId) throw new Error('Kein taskId: ' + JSON.stringify(data));
return [{ json: {
  taskId: taskId,
  theme: $('Lyrics Template').item.json.theme,
  suno_api_key: $('Lyrics Template').item.json.suno_api_key
} }];

const data = $input.first().json;
if (data.code !== 200) throw new Error('Poll Fehler: ' + data.msg);
const songs = data.data?.response?.sunoData || data.data?.sunoData || [];
const ready = songs.filter(s => s && (s.audioUrl || s.audio_url));
if (ready.length === 0) {
  const status = data.data?.status || 'unknown';
  throw new Error('Song noch nicht fertig. Status: ' + status);
}
const song = ready[0];
return [{ json: {
  audioUrl: song.audioUrl || song.audio_url,
  title: song.title || $('Lyrics Template').item.json.theme,
  theme: $('Lyrics Template').item.json.theme
} }];

const result = $input.first().json;
if (!result.success) throw new Error('Video-Build fehlgeschlagen: ' + JSON.stringify(result));
return [{ json: {
  videoPath: result.video_path,
  theme: $('Extract Audio URL').item.json.theme
} }];

